import React from 'react';

function WeekView({ date, entries }) {
  const getWeekDays = () => {
    const week = [];
    const current = new Date(date);
    const day = current.getDay() || 7;
    current.setDate(current.getDate() - day + 1);

    for (let i = 0; i < 7; i++) {
      week.push(new Date(current));
      current.setDate(current.getDate() + 1);
    }

    return week;
  };

  const weekDays = getWeekDays();
  const dayNames = ['Пн', 'Вт', 'Ср', 'Чт', 'Пт', 'Сб', 'Вс'];
  const monthNames = ['янв', 'фев', 'мар', 'апр', 'май', 'июн', 'июл', 'авг', 'сен', 'окт', 'ноя', 'дек'];

  // Временные слоты для отображения
  const timeSlots = [
    '06:00 - 07:00', '07:00 - 08:00', '08:00 - 09:00', '09:00 - 10:00', '10:00 - 11:00', '11:00 - 12:00',
    '12:00 - 13:00', '13:00 - 14:00', '14:00 - 15:00', '15:00 - 16:00', '16:00 - 17:00', '17:00 - 18:00',
    '18:00 - 19:00', '19:00 - 20:00', '20:00 - 21:00', '21:00 - 22:00', '22:00 - 23:00', '23:00 - 00:00'
  ];

  const getDayEntries = (date) => {
    const dateKey = date.toDateString();
    const dayEntry = entries[dateKey];

    if (!dayEntry) return [];

    return [
      ...(dayEntry.morning || []),
      ...(dayEntry.day || []),
      ...(dayEntry.evening || [])
    ];
  };

  const getCategoryColor = (category) => {
    const colors = {
      'Yoga': '#ff6b6b',
      'Boxing': '#4ecdc4',
      'SoftDev': '#45b7d1',
      'MBA': '#96ceb4',
      'English': '#ffeaa7',
      'Oratory': '#ff9ff3',
      'Math': '#feca57',
      'Chinise': '#ffb8b8',
      'Finance': '#c56cf0',
      'Chess': '#ffcccc',
      'Business': '#a8e6cf'
    };
    return colors[category] || '#ddd';
  };

  const formatDate = (date) => {
    return `${date.getDate()} ${monthNames[date.getMonth()]}`;
  };

  const isToday = (date) => {
    const today = new Date();
    return date.toDateString() === today.toDateString();
  };

  const handlePrevWeek = () => {
    const prevWeek = new Date(date);
    prevWeek.setDate(date.getDate() - 7);
    window.location.reload();
  };

  const handleNextWeek = () => {
    const nextWeek = new Date(date);
    nextWeek.setDate(date.getDate() + 7);
    window.location.reload();
  };

  const handleToday = () => {
    window.location.reload();
  };

  return (
    <div className="week-view">
      <div className="week-navigation">
        <button onClick={handlePrevWeek} className="nav-btn">←</button>
        <div className="week-title">
          <h2>
            Неделя {formatDate(weekDays[0])} - {formatDate(weekDays[6])}
          </h2>
          <button onClick={handleToday} className="today-btn">
            Сегодня
          </button>
        </div>
        <button onClick={handleNextWeek} className="nav-btn">→</button>
      </div>

      <div className="week-grid">
        <div className="time-column">
          <div className="time-header">Время</div>
          {timeSlots.map(slot => (
            <div key={slot} className="time-slot">{slot}</div>
          ))}
        </div>

        {weekDays.map((day, dayIndex) => {
          const dayEntries = getDayEntries(day);
          const isCurrentDay = isToday(day);

          return (
            <div key={dayIndex} className={`day-column ${isCurrentDay ? 'today' : ''}`}>
              <div className="day-header">
                <div className="day-name">{dayNames[dayIndex]}</div>
                <div className="day-date">{formatDate(day)}</div>
              </div>

              {timeSlots.map(slot => {
                const slotEntries = dayEntries.filter(entry => entry.timeSlot === slot);

                return (
                  <div key={slot} className="day-slot">
                    {slotEntries.map(entry => (
                      <div
                        key={entry.id}
                        className="week-entry"
                        style={{ backgroundColor: getCategoryColor(entry.category) }}
                      >
                        <div className="entry-category">{entry.category}</div>
                        <div className="entry-practice">{entry.practice}</div>
                        <div className="entry-duration">⏱️ {entry.duration}</div>
                        {entry.repeat && entry.repeat !== 'Не повторять' && (
                          <div className="entry-repeat">🔄</div>
                        )}
                      </div>
                    ))}
                  </div>
                );
              })}
            </div>
          );
        })}
      </div>
    </div>
  );
}

export default WeekView;
